{{ config(
            materialized='table',
                post_hook={
                    "sql": "CREATE OR REPLACE TEMPORARY TABLE temp_extracted_data AS SELECT saleorderdto, JSON_EXTRACT_ARRAY(saleorderdto, \'$.saleOrderItems\') AS saleOrderItems, JSON_EXTRACT_ARRAY(saleorderdto, \'$.shippingPackages\') AS shippingPackages, JSON_EXTRACT_ARRAY(saleorderdto, \'$.returns\') AS returns, JSON_EXTRACT_SCALAR(saleorderdto, \'$.billingAddress.pincode\') AS PINCODE, JSON_EXTRACT_SCALAR(saleorderdto, \'$.channel\') AS marketplace, JSON_EXTRACT_SCALAR(saleorderdto, \'$.source\') AS source, JSON_EXTRACT_SCALAR(saleorderdto, \'$.code\') AS order_id, JSON_EXTRACT_SCALAR(saleorderdto, \'$.displayOrderCode\') AS reference_code, JSON_EXTRACT_SCALAR(saleorderdto, \'$.billingAddress.phone\') AS phone, JSON_EXTRACT_SCALAR(saleorderdto, \'$.billingAddress.name\') AS name, JSON_EXTRACT_SCALAR(saleorderdto, \'$.billingAddress.email\') AS email, datetime(timestamp_millis(CAST(JSON_EXTRACT_SCALAR(saleorderdto, \'$.updated\') AS int)), \"Asia/Kolkata\") AS SHIPPING_LAST_UPDATE_DATE, JSON_EXTRACT_SCALAR(saleorderdto, \'$.currencyCode\') AS currency, JSON_EXTRACT_SCALAR(saleorderdto, \'$.billingAddress.city\') AS city, JSON_EXTRACT_SCALAR(saleorderdto, \'$.billingAddress.state\') AS state, JSON_EXTRACT_SCALAR(saleorderdto, \'$.status\') AS ORDER_STATUS, datetime(timestamp_millis(CAST(JSON_EXTRACT_SCALAR(saleorderdto, \'$.displayOrderDateTime\') AS int)), \"Asia/Kolkata\") AS order_Date, CASE WHEN REPLACE(JSON_EXTRACT_SCALAR(saleorderdto, \'$.cod\'), \'\"\', \'\') = \'true\' THEN \'COD\' ELSE \'Prepaid\' END AS payment_mode, CASE WHEN REPLACE(JSON_EXTRACT_SCALAR(saleorderdto, \'$.code\'), \'\"\', \'\') = \'true\' THEN \'COD\' ELSE \'Prepaid\' END AS payment_method FROM fablestreet-wh.Maplemonk.Unicommerce_Fablestreet_Uniware_GET_ORDERS_BY_IDS ; CREATE OR REPLACE TEMPORARY TABLE temp_order_related AS SELECT ed.PINCODE as pincode, ed.marketplace as marketplace, ed.source as source, ed.order_id as ordeR_id, ed.reference_code reference_code, ed.phone phone, ed.name name, ed.email email, ed.SHIPPING_LAST_UPDATE_DATE SHIPPING_LAST_UPDATE_DATE, REGEXP_REPLACE(JSON_EXTRACT_SCALAR(item, \'$.itemSku\'), \'-$\', \'\') AS sku, JSON_EXTRACT_SCALAR(item, \'$.sellerSkuCode\') AS Marketplace_sku, JSON_EXTRACT_SCALAR(item, \'$.channelMrp\') AS channel_MRP, JSON_EXTRACT_SCALAR(item, \'$.channelProductId\') AS product_id, JSON_EXTRACT_SCALAR(item, \'$.itemName\') AS product_name, ed.currency currency, ed.city city, ed.state state, JSON_EXTRACT_SCALAR(item, \'$.statusCode\') as order_status, ed.order_Date ordeR_date, CAST(JSON_EXTRACT_SCALAR(item, \'$.shippingCharges\') AS FLOAT64) AS shipping_price, CAST(JSON_EXTRACT_SCALAR(item, \'$.packetNumber\') AS FLOAT64) AS SUBORDER_QUANTITY, CAST(JSON_EXTRACT_SCALAR(item, \'$.discount\') AS FLOAT64) AS discount, CAST(JSON_EXTRACT_SCALAR(item, \'$.totalIntegratedGst\') AS FLOAT64) AS tax, CAST(JSON_EXTRACT_SCALAR(item, \'$.sellingPrice\') AS FLOAT64) AS SELLING_PRICE, JSON_EXTRACT_SCALAR(item, \'$.shippingPackageCode\') AS shippingPackageCode, JSON_EXTRACT_SCALAR(item, \'$.shippingPackageStatus\') AS shippingPackageStatus, JSON_EXTRACT_SCALAR(item, \'$.code\') AS saleOrderItemCode, CAST(JSON_EXTRACT_SCALAR(item, \'$.id\') AS STRING) AS SALES_ORDER_ITEM_ID, JSON_EXTRACT_SCALAR(item, \'$.facilityName\') AS warehouse_name, JSON_EXTRACT_SCALAR(shippingPackages,\'$.trackingNumber\') AS AWB, datetime(timestamp_millis(CAST(JSON_EXTRACT_SCALAR(shippingPackages,\'$.invoiceDate\') AS int)), \"Asia/Kolkata\") AS invoiceDate, JSON_EXTRACT_SCALAR(shippingPackages,\'$.invoiceCode\') invoiceCode, ed.payment_mode, ed.payment_method FROM temp_extracted_data ed LEFT JOIN UNNEST(ed.saleOrderItems) AS item LEFT JOIN UNNEST(ed.shippingPackages) AS shippingPackages; CREATE OR REPLACE TEMPORARY TABLE temp_shipping_related AS WITH extracted_items AS ( SELECT REPLACE(JSON_EXTRACT_SCALAR(A, \'$.shippingProvider\'), \'\"\', \'\') AS courier, REPLACE(JSON_EXTRACT_SCALAR(A, \'$.status\'), \'\"\', \'\') AS shipping_status, datetime(timestamp_millis(CAST(JSON_EXTRACT_SCALAR(A, \'$.dispatched\') AS int)), \"Asia/Kolkata\") AS dispatched, datetime(timestamp_millis(CAST(JSON_EXTRACT_SCALAR(A, \'$.delivered\') AS int)), \"Asia/Kolkata\") AS delivered, JSON_EXTRACT_SCALAR(A, \'$.code\') AS shippingPackageCode, c.order_id, JSON_EXTRACT(A, \'$.items\') AS items FROM temp_extracted_data c LEFT JOIN UNNEST(c.shippingPackages) A ) SELECT c.*, cast(JSON_EXTRACT_SCALAR(value, \'$.quantity\') AS int64) AS shippedQuantity, REGEXP_REPLACE(JSON_EXTRACT_SCALAR(value, \'$.itemSku\'), \'-$\', \'\') AS itemSku, FROM extracted_items c left join UNNEST(REGEXP_EXTRACT_ALL(items, r\'\{[^{}]+\}\')) AS value; CREATE OR REPLACE TEMPORARY TABLE temp_returns AS WITH extracted_return_data AS ( SELECT ed.order_id, ed.reference_code, JSON_EXTRACT_ARRAY(A, \'$.returnItems\') AS returnItems FROM temp_extracted_data ed LEFT JOIN UNNEST(ed.returns) AS A ) SELECT erd.order_id AS ordeR_id, erd.reference_code, REPLACE(JSON_EXTRACT_SCALAR(B, \'$.saleOrderItemCode\'), \'\"\', \'\') AS saleOrderItemCode, REGEXP_REPLACE(REPLACE(JSON_EXTRACT_SCALAR(B, \'$.itemSku\'), \'\"\', \'\'), \'-$\', \'\') AS itemSku FROM extracted_return_data erd LEFT JOIN UNNEST(erd.returnItems) AS B WHERE REPLACE(JSON_EXTRACT_SCALAR(B, \'$.saleOrderItemCode\'), \'\"\', \'\') IS NOT NULL; create or replace table fablestreet-wh.Maplemonk.fablestreet_wh_UNICOMMERCE_fact_items_intermediate_final as SELECT o.pincode, o.marketplace, o.source, o.order_id, o.reference_code, o.phone, o.name, o.email, o.SHIPPING_LAST_UPDATE_DATE, o.sku, o.Marketplace_sku, o.product_id, o.product_name, o.currency, o.city, o.state, o.ORDER_STATUS, invoiceCode, invoiceDate, o.order_date , o.shipping_price, CASE WHEN LOWER(o.marketplace) LIKE \'%myntra%\' THEN safe_divide(s.shippedQuantity,count(*) over(partition by o.order_id,o.sku)) WHEN LOWER(o.marketplace) LIKE \'%tata%\' THEN o.SUBORDER_QUANTITY/1000 WHEN cast(O.SUBORDER_QUANTITY as int64) = 0 then 1 ELSE o.SUBORDER_QUANTITY END AS SUBORDER_QUANTITY, o.discount, o.tax, ifnull(o.SELLING_PRICE,0) + ifnull(O.shipping_price,0) as SELLING_PRICE, o.shippingPackageCode, o.shippingPackageStatus, o.saleOrderItemCode, o.SALES_ORDER_ITEM_ID, o.AWB, o.channel_MRP, o.warehouse_name, o.payment_mode, o.payment_method, s.courier, s.shipping_status, s.shippedQuantity, s.dispatched AS Dispatch_date, s.delivered AS Delivered_Date, CASE WHEN r.itemSku IS NOT NULL THEN 1 ELSE 0 END AS return_flag, CASE WHEN (CASE WHEN r.itemSku IS NOT NULL THEN 1 ELSE 0 END) = 1 THEN (CASE WHEN LOWER(o.marketplace) LIKE \'%myntra%\' THEN s.shippedQuantity ELSE o.SUBORDER_QUANTITY END) ELSE 0 END AS return_quantity, CASE WHEN order_status = \'CANCELLED\' THEN CASE WHEN LOWER(o.marketplace) LIKE \'%myntra%\' THEN s.shippedQuantity ELSE o.SUBORDER_QUANTITY END ELSE 0 END AS cancelled_quantity, null AS new_customer_flag, null AS acquisition_product, CASE WHEN UPPER(order_status) = \'COMPLETE\' THEN CAST(s.delivered AS DATE) - CAST(order_date AS DATE) ELSE CAST(CURRENT_DATE AS DATE) - CAST(order_date AS DATE) END AS days_in_shipment, FROM temp_order_related o LEFT JOIN temp_shipping_related s ON o.shippingPackageCode = s.shippingPackageCode AND o.sku = s.itemSku AND o.order_id = s.order_id LEFT JOIN temp_returns r ON r.saleOrderItemCode = o.saleOrderItemCode AND r.order_id = o.order_id ; create or replace table fablestreet-wh.Maplemonk.fablestreet_wh_customerID_test_Final as with new_phone_numbers as ( select contact_num ,9700000000 + row_number() over( order by contact_num asc ) as maple_monk_id from ( select distinct SUBSTR(REGEXP_REPLACE(REPLACE(phone, \' \', \'\'),\'[^a-zA-Z0-9]\',\'\'),-10) as contact_num from fablestreet-wh.Maplemonk.fablestreet_wh_UNICOMMERCE_fact_items_intermediate_final ) a ), int as ( select contact_num,email,coalesce(maple_monk_id,id2) as maple_monk_id from ( select contact_num, email,maple_monk_id,9800000000+row_number() over(partition by maple_monk_id is NULL order by email asc ) as id2 from ( select distinct coalesce(p.contact_num,SUBSTR(REGEXP_REPLACE(REPLACE(e.contact_num, \' \', \'\'),\'[^a-zA-Z0-9]\',\'\'),-10)) as contact_num, e.email,maple_monk_id from ( select replace(phone,\' \',\'\') as contact_num,email from fablestreet-wh.Maplemonk.fablestreet_wh_UNICOMMERCE_fact_items_intermediate_final ) e left join new_phone_numbers p on p.contact_num = SUBSTR(REGEXP_REPLACE(REPLACE(e.contact_num, \' \', \'\'),\'[^a-zA-Z0-9]\',\'\'),-10) ) a ) b ) select contact_num,email,case when email is not null and email <> \'\' then min(maple_monk_id) over (partition by email ) else maple_monk_id end maple_monk_id from int where coalesce(contact_num,email) is not NULL; create or replace table fablestreet-wh.Maplemonk.fablestreet_wh_unicommerce_fact_items as select coalesce(c.maple_monk_id,c.maple_monk_id) customer_id, o.*, null as acquisition_date from fablestreet-wh.Maplemonk.fablestreet_wh_UNICOMMERCE_fact_items_intermediate_final o left join (select distinct contact_num phone,maple_monk_id from fablestreet-wh.Maplemonk.fablestreet_wh_customerID_test_Final )c on replace(c.phone,\' \',\'\') = replace(o.phone,\' \',\'\') where o.order_date is not null; CREATE OR REPLACE TABLE fablestreet-wh.Maplemonk.fablestreet_wh_unicommerce_fact_items_TEMP_Category as select fi.*, coalesce(fi.sku) AS SKU_CODE, upper(p.PRODUCT_name) as PRODUCT_NAME_Final, Upper(p.CATEGORY) AS Product_Category, Upper(p.Variant_sku) AS Variant_sku, Collection_Name, p.mrp from fablestreet-wh.Maplemonk.fablestreet_wh_unicommerce_fact_items fi left join (select * from ( select upper(cast(trim(title) as string)) PRODUCT_name, upper(cast(trim(category) as string)) as Category, upper(cast(trim(Variant_sku) as string)) Variant_sku, upper(cast(trim(Collection_Name) as string)) Collection_Name, cast(trim(mrp) as float64) as mrp, row_number() over (partition by replace(Variant_sku,\' \',\'\') order by 1) rw from fablestreet-wh.Maplemonk.fablestreet_gs_sku_master ) where rw = 1 ) p on split(lower(replace(fi.sku,\' \',\'\')),\'-\')[OFFSET(0)] = lower(replace(p.Variant_sku,\' \',\'\')) ; CREATE OR REPLACE TABLE fablestreet-wh.Maplemonk.fablestreet_wh_unicommerce_fact_items AS SELECT * FROM (select *, row_number() over (partition by reference_code, saleorderitemcode order by SHIPPING_LAST_UPDATE_DATE desc) rw1 from fablestreet-wh.Maplemonk.fablestreet_wh_unicommerce_fact_items_TEMP_Category ) where rw1=1; CREATE OR REPLACE TEMPORARY TABLE temp_extracted_base AS SELECT JSON_EXTRACT_SCALAR(saleorderdto, \'$.channel\') AS Marketplace, JSON_EXTRACT_SCALAR(saleorderdto, \'$.source\') AS Source, JSON_EXTRACT_SCALAR(saleorderdto, \'$.code\') AS order_id, JSON_EXTRACT_SCALAR(saleorderdto, \'$.displayOrderCode\') AS reference_code, JSON_EXTRACT_SCALAR(saleorderdto, \'$.billingAddress.phone\') AS phone, JSON_EXTRACT_SCALAR(saleorderdto, \'$.billingAddress.email\') AS email, datetime(timestamp_millis(CAST(JSON_EXTRACT_SCALAR(saleorderdto, \'$.displayOrderDateTime\') AS INT64)), \"Asia/Kolkata\") AS order_date, JSON_EXTRACT_ARRAY(saleorderdto, \'$.returns\') AS returns_raw_array FROM fablestreet-wh.Maplemonk.Unicommerce_Fablestreet_Uniware_GET_ORDERS_BY_IDS; CREATE OR REPLACE TABLE fablestreet-wh.Maplemonk.fablestreet_wh_UNICOMMERCE_RETURNS_INTERMEDIATE AS SELECT base.Marketplace, base.Source, base.order_id, base.phone, base.email, base.order_date, base.reference_code, JSON_EXTRACT_SCALAR(ret, \'$.code\') AS return_displaycode, JSON_EXTRACT_SCALAR(ret, \'$.statusCode\') AS return_status, datetime(timestamp_millis(CAST(JSON_EXTRACT_SCALAR(ret, \'$.inventoryReceivedDate\') AS INT64)), \"Asia/Kolkata\") AS inventory_received_date, datetime(timestamp_millis(CAST(JSON_EXTRACT_SCALAR(ret, \'$.returnCompletedDate\') AS INT64)), \"Asia/Kolkata\") AS return_complete_date, JSON_EXTRACT_SCALAR(ret, \'$.returnInvoiceDisplayCode\') AS return_invoice_display_code, JSON_EXTRACT_SCALAR(ret, \'$.shippingProvider\') AS return_courier, JSON_EXTRACT_SCALAR(ret, \'$.providerStatus\') AS return_provider_shipping_status, JSON_EXTRACT_SCALAR(ret, \'$.trackingNumber\') AS return_tracking_number, JSON_EXTRACT_SCALAR(ret, \'$.type\') AS return_type, JSON_EXTRACT_SCALAR(ritem, \'$.saleOrderItemCode\') AS sale_order_item_code, JSON_EXTRACT_SCALAR(ritem, \'$.itemSku\') AS item_sku, JSON_EXTRACT_SCALAR(ritem, \'$.itemName\') AS item_name, JSON_EXTRACT_SCALAR(ritem, \'$.inventoryType\') AS inventory_type FROM temp_extracted_base base LEFT JOIN UNNEST(base.returns_raw_array) AS ret LEFT JOIN UNNEST(JSON_EXTRACT_ARRAY(ret, \'$.returnItems\')) AS ritem;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from maplemonk.INFORMATION_SCHEMA.TABLES
